'use strict';

const { tokenize } = require('./tokenizer');
const { parse } = require('./parser');
const { evaluateAst } = require('./evaluator');
const { ExprError } = require('./errors');

/**
 * evaluate(source, variables = {}) evaluates one complete arithmetic formula.
 * The source is a string. Whitespace separates tokens and is otherwise ignored.
 * Numbers are nonnegative literals: integers, decimals (1.5, .5, 5.), and an
 * optional e/E exponent with an optional sign (1.5e-3). Signs are unary operators.
 * Identifiers match [A-Za-z_][A-Za-z0-9_]* and read own properties of variables.
 * Supplied variable values are numbers. An unknown variable raises ExprError at
 * its identifier. Each occurrence is read once, in left-to-right evaluation
 * order; getter-backed properties are supported. No variable object is mutated.
 *
 * Parentheses group expressions. Calls are only to built-ins min, max, and abs.
 * min/max take one or more comma-separated expressions; abs takes exactly one.
 * Arguments are evaluated left to right. Unknown calls and wrong argument counts
 * are syntax errors (detected while parsing, before anything is evaluated) and
 * raise ExprError at the function identifier. There are no implicit products,
 * assignments, strings, user-defined functions, or trailing argument commas.
 *
 * Binary operators are + - * / // % **. + and - have equal precedence; *, /,
 * // and % share the next higher precedence. These operators associate left.
 * Unary + and - bind below ** on its left, while the right operand of ** may
 * have a unary sign: -2 ** 2 is -4 and 2 ** -1 is 0.5. ** associates right:
 * 2 ** 3 ** 2 is 512. Thus the grammar is:
 *   comparison := sum (('<' | '<=' | '>' | '>=' | '==' | '!=') sum)*
 *   sum        := product (('+' | '-') product)*
 *   product    := unary (('*' | '/' | '//' | '%') unary)*
 *   unary      := ('+' | '-') unary | power
 *   power      := primary ('**' unary)?
 *   primary    := number | identifier | '(' comparison ')'
 *                 | identifier '(' comparison (',' comparison)* ')'
 * The call grammar is subject to the arity restrictions above.
 *
 * Comparisons have lower precedence than arithmetic and produce booleans.
 * They chain, rather than comparing an intermediate boolean: a < b <= c means
 * a < b and b <= c. Shared operands are evaluated once. A false comparison
 * short-circuits the remaining operands (but the whole source is parsed first).
 * Parenthesized comparison results used in arithmetic are numbers 0/1, as in
 * Python; numeric equality likewise treats these booleans as 0/1.
 *
 * // is floor division, not truncation; % has the divisor's sign unless zero.
 * For integer inputs, a == (a // b) * b + (a % b), so -7 // 2 is -4,
 * -7 % 3 is 2, and 7 % -3 is -2. Zero results of // and % are positive zero.
 * /, // and % with a zero divisor raise ExprError at the operator token.
 * Arithmetic otherwise uses JavaScript Number precision, not arbitrary-precision
 * Python integers. Inputs/results need not emulate Python overflow exceptions.
 *
 * Syntax errors and invalid characters raise ExprError with .column: the 1-based
 * UTF-16 offset of the offending token; unexpected end is source.length + 1,
 * including trailing whitespace. Error message wording is not part of the API.
 * Tokenization, parsing and evaluation must stay linear in the formula length
 * for long flat arithmetic and comparison chains: a formula with 100,000+
 * operands must evaluate in well under a second and must not recurse once per
 * operand. Deeply nested parentheses or ** chains may be limited by the stack.
 */
function evaluate(source, variables = {}) {
  return evaluateAst(parse(tokenize(source)), variables);
}

module.exports = { evaluate, ExprError };
'use strict';

/** A formula error, positioned at a 1-based UTF-16 source column. */
class ExprError extends Error {
  constructor(message, column) {
    super(message);
    this.name = 'ExprError';
    this.column = column;
  }
}

module.exports = { ExprError };
'use strict';

const { ExprError } = require('./errors');

/** Convert source to positioned tokens without repeatedly slicing its suffix. */
function tokenize(source) {
  const tokens = [];
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  let offset = 0;
  while (offset < source.length) {
    const column = offset + 1;
    while (offset < source.length && /\s/.test(source[offset])) offset += 1;
    if (offset === source.length) break;
    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      tokens.push({ type: 'number', value: Number(numeric[0]), column });
      offset = number.lastIndex;
      continue;
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      tokens.push({ type: 'identifier', value: name[0], column });
      offset = identifier.lastIndex;
      continue;
    }
    const pair = source.slice(offset, offset + 2);
    if (['**', '//', '<=', '>=', '==', '!='].includes(pair)) {
      tokens.push({ type: 'operator', value: pair, column });
      offset += 2;
    } else if ('+-*/%<>() ,'.includes(source[offset]) && source[offset] !== ' ') {
      tokens.push({ type: 'operator', value: source[offset], column });
      offset += 1;
    } else {
      throw new ExprError('Unexpected character', column);
    }
  }
  tokens.push({ type: 'eof', value: '', column: source.length + 1 });
  return tokens;
}

module.exports = { tokenize };
'use strict';

const { ExprError } = require('./errors');

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  function comparison() {
    let left = sum();
    while (['<', '<=', '>', '>=', '==', '!='].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, sum());
    }
    return left;
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = power();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, power());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
    }
    return primary();
  }

  function power() {
    let left = unary();
    while (is('**')) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
      take();
      const args = [];
      if (!is(')')) {
        args.push(comparison());
        while (is(',')) {
          take();
          args.push(comparison());
        }
      }
      expect(')');
      if (!['min', 'max', 'abs'].includes(token.value)) {
        throw new ExprError('Unknown function', token.column);
      }
      if (!args.length || (token.value === 'abs' && args.length !== 1)) {
        throw new ExprError('Wrong argument count', token.column);
      }
      return { type: 'call', name: token.value, args };
    }
    if (token.value === '(') {
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

module.exports = { parse };
'use strict';

const { ExprError } = require('./errors');

function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**': return left ** right;
    case '//': {
      const quotient = Math.trunc(left / right);
      return quotient === 0 ? 0 : quotient;
    }
    case '%': {
      const remainder = left % right;
      if (remainder === 0) return 0;
      return remainder;
    }
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
function evaluateAst(root, variables) {
  const frames = [{ node: root, phase: 0 }];
  let result;
  while (frames.length) {
    const frame = frames[frames.length - 1];
    const node = frame.node;
    if (node.type === 'number') {
      result = node.value;
      frames.pop();
    } else if (node.type === 'variable') {
      if (!Object.prototype.hasOwnProperty.call(variables, node.name)) {
        throw new ExprError('Unknown variable', node.column);
      }
      result = variables[node.name];
      frames.pop();
    } else if (node.type === 'unary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operand, phase: 0 });
      } else {
        result = node.operator.value === '-' ? -Number(result) : Number(result);
        frames.pop();
      }
    } else if (node.type === 'binary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.left, phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.phase = 2;
        frames.push({ node: node.right, phase: 0 });
      } else {
        result = apply(node.operator, frame.left, result);
        frames.pop();
      }
    } else if (node.type === 'comparison') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operands[0], phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.index = 0;
        frame.phase = 2;
        frames.push({ node: node.operands[1], phase: 0 });
      } else {
        const right = result;
        if (!apply(node.operators[frame.index], frame.left, right)) {
          result = false;
          frames.pop();
        } else if (frame.index + 1 === node.operators.length) {
          result = true;
          frames.pop();
        } else {
          frame.left = right;
          frame.index += 1;
          frames.push({ node: node.operands[frame.index + 1], phase: 0 });
        }
      }
    } else if (node.type === 'call') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frame.index = 0;
        frames.push({ node: node.args[0], phase: 0 });
      } else {
        const value = Number(result);
        if (frame.index === 0) frame.value = value;
        else if (node.name === 'min') frame.value = Math.min(frame.value, value);
        else frame.value = Math.max(frame.value, value);
        frame.index += 1;
        if (frame.index === node.args.length) {
          result = node.name === 'abs' ? Math.abs(frame.value) : frame.value;
          frames.pop();
        } else {
          frames.push({ node: node.args[frame.index], phase: 0 });
        }
      }
    } else {
      throw new Error('Invalid AST node');
    }
  }
  return result;
}

module.exports = { evaluateAst };


