'use strict';

const { ExprError } = require('./errors');

const COMPARISONS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCTS = new Set(['*', '/', '//', '%']);
const FUNCTIONS = new Set(['min', 'max', 'abs']);

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().type === 'operator' && current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  // comparison := sum (op sum)*, kept as one chain node so a < b < c is a < b and b < c.
  function comparison() {
    const first = sum();
    if (!(current().type === 'operator' && COMPARISONS.has(current().value))) return first;
    const operands = [first];
    const operators = [];
    while (current().type === 'operator' && COMPARISONS.has(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (current().type === 'operator' && PRODUCTS.has(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  // unary := ('+' | '-') unary | power; collected iteratively to avoid per-sign recursion.
  function unary() {
    const signs = [];
    while (is('+') || is('-')) signs.push(take());
    let node = power();
    for (let i = signs.length - 1; i >= 0; i -= 1) {
      node = { type: 'unary', operator: signs[i], operand: node };
    }
    return node;
  }

  // power := primary ('**' unary)?; right-associative through unary -> power.
  function power() {
    const base = primary();
    if (!is('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function call(token) {
    const name = token.value;
    if (!FUNCTIONS.has(name)) throw new ExprError('Unknown function', token.column);
    take(); // '('
    if (is(')')) throw new ExprError('Wrong argument count', token.column);
    const args = [comparison()];
    while (is(',')) {
      if (name === 'abs') throw new ExprError('Wrong argument count', token.column);
      take();
      args.push(comparison());
    }
    expect(')');
    return { type: 'call', name, args };
  }

  function primary() {
    const token = current();
    if (token.type === 'number') {
      take();
      return { type: 'number', value: token.value };
    }
    if (token.type === 'identifier') {
      take();
      if (is('(')) return call(token);
      return { type: 'variable', name: token.value, column: token.column };
    }
    if (is('(')) {
      take();
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

module.exports = { parse };

